insert into tl_admin.tjbb_dt_d01003(swjgdm,bblc,mldm,paramhash,usd_amt_sq,ts_amt_sq,usd_amt,ts_amt, usd_amt_tb,ts_amt_tb) select #{swjgdm}, to_char(row_number() over (order by mldm),'0000') bblc, mldm,'TEMP-'||#{pramHash},sum(usd_amt_sq),sum(ts_amt_sq),sum(usd_amt),sum(ts_amt), decode(sum(usd_amt_sq),0,0,ROUND((sum(usd_amt)-sum(usd_amt_sq))/sum(usd_amt_sq),4)), decode(sum(ts_amt_sq),0,0,ROUND((sum(ts_amt)-sum(ts_amt_sq))/sum(ts_amt_sq),4)) from ( select '1' as mldm,1 as usd_amt_sq ,1 as ts_amt_sq,1 as usd_amt,1 as ts_amt from dual where 1>2
union all select ml.spml as mldm,sum(T.usd_amt_sq) as usd_amt_sq,sum(T.ts_amt_sq) as ts_amt_sq,sum(T.usd_amt) as usd_amt,sum(T.ts_amt) ts_amt from( select substr(mx.cksp_dm,1,2) as mxCode, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mdtse else 0 end) as ts_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mdtse else 0 end) as ts_amt from tl_tssh.glxt_bb_shxt_djxx dj,tl_tssh.ckts_sb_mdt_ckmx mx where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
and dj.qyhgdm = #{cxtjDTO.qyhgdm}
and mx.cksp_dm like #{cxtjDTO.cmcode} || '%'
group by substr(mx.cksp_dm,1,2) ) T ,tl_admin.dm_spfl sp,tl_admin.dm_spml ml where sp.spdl=T.mxCode and ml.spml=sp.spml group by ml.spml
union all select ml.spml as mldm,sum(T.usd_amt_sq) as usd_amt_sq,sum(T.ts_amt_sq) as ts_amt_sq,sum(T.usd_amt) as usd_amt,sum(T.ts_amt) ts_amt from( select substr(mx.cksp_dm,1,2) as mxCode, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.tse else 0 end) as ts_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.tse else 0 end) as ts_amt from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_mts_ckmx mx where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
and dj.qyhgdm = #{cxtjDTO.qyhgdm}
and mx.cksp_dm like #{cxtjDTO.cmcode} || '%'
group by substr(mx.cksp_dm,1,2) ) T ,tl_admin.dm_spfl sp,tl_admin.dm_spml ml where sp.spdl=T.mxCode and ml.spml=sp.spml group by ml.spml
union all select ml.spml as mldm,sum(T.usd_amt_sq) as usd_amt_sq,sum(T.ts_amt_sq) as ts_amt_sq,sum(T.usd_amt) as usd_amt,sum(T.ts_amt) ts_amt from( select substr(mx.cksp_dm,1,2) as mxCode, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.tse else 0 end) as ts_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.tse else 0 end) as ts_amt from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_wzf_ckmx mx where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
and dj.qyhgdm = #{cxtjDTO.qyhgdm}
and mx.cksp_dm like #{cxtjDTO.cmcode} || '%'
group by substr(mx.cksp_dm,1,2) ) T ,tl_admin.dm_spfl sp,tl_admin.dm_spml ml where sp.spdl=T.mxCode and ml.spml=sp.spml group by ml.spml
) u group by mldm

