group by nvl(dj.shxyno,dj.nsrdjno),dj.nsrmc
union all
select nvl(dj.shxyno,dj.nsrdjno) as nsrsbh, dj.nsrmc, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.tse else 0 end) as ts_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.tse else 0 end) as ts_amt from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_mts_ckmx mx where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
