insert into tl_admin.tjbb_dt_d01006(swjgdm,bblc,tsl,paramhash,usd_amt_sq,usd_amt, usd_amt_tb)
select #{swjgdm}, to_char(row_number() over (order by tsl),'0000') bblc, tsl||'%','TEMP-'||#{pramHash},sum(usd_amt_sq),sum(usd_amt), decode(sum(usd_amt_sq),0,0,ROUND((sum(usd_amt)-sum(usd_amt_sq))/sum(usd_amt_sq),4)) from ( select 1 as tsl,1 as usd_amt_sq , 1 as usd_amt from dual where 1>2
union all
select round(mx.tsl,0), sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_mdt_ckmx mx where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
