group by round(mx.tsl,0)
union all
select round(case when mylaj=0 then 0 else mx.tse/mx.mylaj end,0), sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_mts_ckmx mx where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
and dj.qyhgdm = #{cxtjDTO.qyhgdm}
group by round(case when mylaj=0 then 0 else mx.tse/mx.mylaj end,0)
union all
select round(mx.tsl,0), sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_wzf_ckmx mx where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
