) u group by tsl

insert into tl_admin.tjbb_dt_d01007(swjgdm,bblc, sjhy_dm,hydm,hymc,qyhs,paramhash,usd_amt_sq,ts_amt_sq,usd_amt,ts_amt, usd_amt_tb,ts_amt_tb) select #{swjgdm}, to_char(row_number() over (order by sjhy_dm,hydm),'0000') bblc, sjhy_dm,hydm,max(hymc),sum(qyhs), 'TEMP-'||#{pramHash},sum(usd_amt_sq),sum(ts_amt_sq),sum(usd_amt),sum(ts_amt), decode(sum(usd_amt_sq),0,0,ROUND((sum(usd_amt)-sum(usd_amt_sq))/sum(usd_amt_sq),4)), decode(sum(ts_amt_sq),0,0,ROUND((sum(ts_amt)-sum(ts_amt_sq))/sum(ts_amt_sq),4)) from (
select '1' as sjhy_dm,'1' as hydm,'1' as hymc,1 as qyhs, 1 as usd_amt_sq ,1 as ts_amt_sq,1 as usd_amt,1 as ts_amt from dual where 1>2
union all
select t.sjhy_dm,ZZ.hydm,ZZ.hymc,qyhs,ZZ.usd_amt_sq,ZZ.ts_amt_sq,ZZ.usd_amt,ZZ.ts_amt from ( select dj.hydm,hy.hymc,count(distinct dj.djxh_js) as qyhs, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mylaj else 0 end) as usd_amt_sq, sum(case when ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.mdtse else 0 end) as ts_amt_sq, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mylaj else 0 end) as usd_amt, sum(case when ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.mdtse else 0 end) as ts_amt from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_mdt_ckmx mx, tl_admin.dm_hy_js hy where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and dj.hydm=hy.hy_dm and ((ckrq_1 between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (ckrq_1 between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and mx.gbcode in
#{item}
and dj.qyhgdm = #{cxtjDTO.qyhgdm}
