insert into tl_admin.tjbb_dt_d01010(swjgdm,bblc, sjxzqh,xzqh,mc,paramhash,jhamt_sq,tse_sq,jhamt,tse, jhamt_tb,tse_tb) select #{swjgdm}, to_char(row_number() over (order by xzqh,mc),'0000') bblc, max(sjxzqh) as sjxzqh,xzqh,max(mc), 'TEMP-'||#{pramHash},sum(jhamt_sq),sum(tse_sq),sum(jhamt),sum(tse), decode(sum(jhamt_sq),0,0,ROUND((sum(jhamt)-sum(jhamt_sq))/sum(jhamt_sq),4)), decode(sum(tse_sq),0,0,ROUND((sum(tse)-sum(tse_sq))/sum(tse_sq),4)) from (
select '1' as sjxzqh,'1' as xzqh,'1' as mc, 1 as jhamt_sq ,1 as tse_sq,1 as jhamt,1 as tse from dual where 1>2
union all
select substr(mx.xzqh,1,2) as sjxzqh ,mx.xzqh,dm.mc, sum(case when kprq between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.jsje else 0 end) as jhamt_sq, sum(case when kprq between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12) then mx.tse else 0 end) as tse_sq, sum(case when kprq between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.jsje else 0 end) as jhamt, sum(case when kprq between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd} then mx.tse else 0 end) as tse from tl_tssh.glxt_bb_shxt_djxx dj, tl_tssh.ckts_sb_mts_jhmx mx, tl_admin.dm_xzqh dm where dj.swjgdm like #{cxtjDTO.swjgDm}||'%' and mx.tsswjg_dm like #{cxtjDTO.swjgDm}||'%' and dj.djxh_js=mx.djxh and mx.xzqh=dm.dm and ((kprq between add_months(#{cxtjDTO.cksjStart},-12) and add_months(#{cxtjDTO.cksjEnd},-12)) or (kprq between #{cxtjDTO.cksjStart} and #{cxtjDTO.cksjEnd}))
and exists(select 1 from tl_tssh.ckts_sb_mts_ckmx ck where ck.djxh=mx.djxh and ck.glh=mx.glh and ck.tsswjg_dm=mx.tsswjg_dm and ck.gbcode in
#{item}
)
and substr(mx.cksp_dm,1,2) in (select spdl from tl_admin.dm_spfl where spml in
#{item}
)
and round(mx.tsl,0) in
#{item}
and dj.qyhgdm = #{cxtjDTO.qyhgdm}
group by mx.xzqh,dm.mc
) u group by xzqh,mc

begin

    update tl_admin.TJBB_DT_E01001 t
    set
    ${item.month} =(
    select
    decode(nvl(sum(usd_amt),0),0,t.${item.month},sum(usd_amt))
    from
    (
    select nvl(sum(mylaj),0) as usd_amt from TL_TSSH.ckts_sb_mdt_ckmx
    where to_char(ckrq_1,'yyyymm')=concat(#{ssny},#{item.yue})
    and tsswjg_dm like #{qxdm}||'%'
    union all
    select nvl(sum(mylaj),0) as usd_amt from TL_TSSH.ckts_sb_mts_ckmx
    where to_char(ckrq_1,'yyyymm')=concat(#{ssny},#{item.yue})
    and tsswjg_dm like #{qxdm}||'%'
    union all
    select nvl(sum(mylaj),0) as usd_amt from TL_TSSH.ckts_sb_wzf_ckmx
    where to_char(ckrq_1,'yyyymm')=concat(#{ssny},#{item.yue})
    and tsswjg_dm like #{qxdm}||'%'
    )) where bblc='07' and swjgdm=#{swjgdm} and ssny=#{ssny};

    update TJBB_DT_E01001 t
    set
    ${item.month} =
    (
    select decode(nvl(${item.month},0),0,t.${item.month},${item.month}) from TJBB_DT_E01001 a
    where a.bblc='07' and swjgdm=#{swjgdm} and ssny=#{lastssny}
    ) where bblc='08' and swjgdm=#{swjgdm} and ssny=#{ssny};

    update TJBB_DT_E01001 t
    set
    ${item.month} =
    (
    select decode(nvl(${item.month},0),0,t.${item.month},${item.month}) from TJBB_DT_E01001 a
    where a.bblc='04' and swjgdm=#{swjgdm} and ssny=#{lastssny}
    ) where bblc='05' and swjgdm=#{swjgdm} and ssny=#{ssny};

    update TJBB_DT_E01001 t
    set
    ${item.month} =
    (
    select decode(nvl(${item.month},0),0,t.${item.month},${item.month}) from TJBB_DT_E01001 a
    where a.bblc='01' and swjgdm=#{swjgdm} and ssny=#{lastssny}
    ) where bblc='02' and swjgdm=#{swjgdm} and ssny=#{ssny};

COMMIT;
end;

mapper.update:
update tl_admin.TJBB_DT_E01001
set ${updateColumn} = #{updateValue}
where bblc=#{bblc} and swjgdm=#{swjgdm} and ssny=#{ssny}
